from collections import Counter

def is_n_straight_hand_brute(hand, group_size):
    if len(hand) % group_size != 0:
        return False
    count = Counter(hand)

    def helper():
        if not count:
            return True
        start = min(count)                                  # smallest remaining value
        for i in range(group_size):
            v = start + i
            if count.get(v, 0) == 0:
                return False
            count[v] -= 1
            if count[v] == 0:
                del count[v]
        if helper():
            return True
        # backtrack (not actually needed here since the choice is forced, but shown for brute-force framing)
        for i in range(group_size):
            count[start + i] = count.get(start + i, 0) + 1
        return False

    return helper()

