from collections import Counter

def is_n_straight_hand(hand, group_size):
    if len(hand) % group_size != 0:
        return False
    count = Counter(hand)
    for start in sorted(count):
        need = count[start]
        if need > 0:
            for i in range(group_size):
                if count.get(start + i, 0) < need:            # not enough of this consecutive value
                    return False
                count[start + i] -= need
    return True

