import java.util.*;

public class Main {
    static boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;
        TreeMap<Integer, Integer> count = new TreeMap<>();
        for (int c : hand) count.merge(c, 1, Integer::sum);
        for (int start : new ArrayList<>(count.keySet())) {
            int need = count.get(start);
            if (need > 0) {
                for (int i = 0; i < groupSize; i++) {
                    int c = count.getOrDefault(start + i, 0);
                    if (c < need) return false;                   // not enough of this consecutive value
                    count.put(start + i, c - need);
                }
            }
        }
        return true;
    }
}

