using namespace std;

bool isNStraightHand(vector<int>& hand, int groupSize) {
    if (hand.size() % groupSize != 0) return false;
    map<int,int> count;
    for (int c : hand) count[c]++;
    for (auto& [start, need] : count) {
        if (need > 0) {
            for (int i = 0; i < groupSize; i++) {
                if (count[start + i] < need) return false;          // not enough of this consecutive value
                count[start + i] -= need;
            }
        }
    }
    return true;
}
